3396	+import 'dart:async';
3397	+
3398	+import 'package:cerne/features/chat/domain/services/connectivity_watcher.dart';
3399	+
3400	+/// A controllable fake `ConnectivityWatcher` — shared across every test
3401	+/// that constructs a `ChatCubit` directly (never through real DI), mirroring
3402	+/// every other hand-rolled fake domain service in this suite (no mocktail
3403	+/// stub needed: every caller just wants to push `true`/`false` and assert
3404	+/// the cubit's reaction). Emits nothing until [emit] is called — a test
3405	+/// that never exercises offline/online behavior never has to drive it at
3406	+/// all, and `ChatCubit`'s own `_isOffline` simply stays at its `false`
3407	+/// default.
3408	+class FakeConnectivityWatcher implements ConnectivityWatcher {
3409	+  final _controller = StreamController<bool>.broadcast();
3410	+
3411	+  @override
3412	+  Stream<bool> watch() => _controller.stream;
3413	+
3414	+  /// Pushes a new online ([isOnline] `true`) / offline (`false`) reading.
3415	+  void emit(bool isOnline) => _controller.add(isOnline);
3416	+
3417	+  /// Pushes a stream-level error — exercises a caller's RNF09 "never
3418	+  /// crashes" handling of a connectivity-watch failure (e.g. the real
3419	+  /// `connectivity_plus` platform channel being unavailable).
3420	+  void emitError(Object error) => _controller.addError(error);
3421	+
3422	+  Future<void> close() => _controller.close();
3423	+}
